        helpSettings5: "AI Assistant設定はこのタブから移動しました——Promptタブ・Taggerタブ・AI TOOLタブそれぞれが独自の⚙設定ボタン（バックエンド・URL・モデル・Thinking mode・Max tokens・モデルのアンロード）を持ち、個別に保存されます",
        helpSettings6: "デフォルトワークフローの設定・解除",
