        helpSettings8: "データ管理：設定・メタデータ・プロンプトなど主要データをJSONにエクスポート、またはインポートして復元。インポート後はComfyUIを再起動してください。",
        helpSettings15: "フルバックアップ (ZIP)：上記のJSONエクスポートと異なり、フォルダ形式のデータ（AI Skills、Lab Plan、Video Plan、Styleプリセット）とTaggerデータベースも含みます。復元すると既存ファイルは上書きされます。復元後はComfyUIを再起動してください。",
        helpSettings16: "フルバックアップのボタン上にある2つのチェックボックスで、デフォルトワークフローフォルダーとImpact Packのwildcardフォルダーもエクスポートに含められます。どちらもエクスポート専用で自動復元はされません。必要な場合はZIP内の_external/フォルダから手動でコピーしてください。",
        helpSettings9: "各セクションはアコーディオン式で折りたたみ可能",
        helpSettings10: "Wildcard Integration：WFSのワイルドカードディレクトリをComfyUI-Impact-Packのwildcardsディレクトリへリンク（Windowsはジャンクション、他OSはシンボリックリンク）。既存ファイルは自動で移行されます",
        helpSettings11: "テキストサイズ：スライダー1本（10〜28px）でプロンプト・チャット全テキストエリアのフォントサイズを一括調整 — GenerateUI ポジティブ/ネガティブプロンプト、AIアシスタントチャット入力、プリセット ポジティブ/ネガティブ、ワイルドカードプロンプト・ファイルエディタ、メタデータプロンプト全文プレビュー；即時反映・保存で確定",
        helpSettings12: "RAW JSON カラー：GenerateUI の Raw JSON エディタの構文ハイライト色（6色）をカスタマイズ — デフォルトテキスト・名前/スケジューラー・タイトル・幅/高さ・プロンプト/テキスト・画像/ファイル；カラーピッカーで即時反映；「デフォルトにリセット」で元の配色に戻す",
        helpSettings13: "CivitAI ホスト：civitai.com（SFWのみ）と civitai.red（制限なし）を切り替え — ModelsタブのCivitAIパネルでモデルリンクをクリックしたときに開くサイトを指定",
        helpSettings14: "GenerateUI Modelタブ ハイライト色：GenerateUIのModelタブで、読み込んだワークフローに実際に該当ノードが含まれる場合にCheckpoint/VAE/Diffusion Model/Text Encoder/ControlNet/Hypernetworkのラベルおよび LoRA 列見出しを彩色する色を指定；デフォルトは明るい緑；変更は即時反映、「デフォルトにリセット」で元に戻す",
