        helpTrouble1: "ComfyUIに接続できない：ComfyUIで画像生成できるか確認、設定タブでURL確認、ブラウザ更新・再起動",
        helpTrouble2: "AIアシスタントに接続できない：設定タブの接続テストボタンで確認；Ollamaの場合は起動とモデルのダウンロードを確認；LM StudioまたはLemonadeの場合はサーバー起動とモデルのロードを確認",
        helpTrouble3: "ワークフローが表示されない：更新ボタン押下、ComfyUIで読み込めるか確認、ブラウザ・ComfyUI再起動",
