        helpPrompt11: "创建/编辑/删除已注册的Style（与GenerateUI的Style下拉菜单、Batch标签、Style Catalog使用的是同一批数据）：点击列表中的名称进行编辑，或点击「+ New」创建空白条目；字段包括Name、Positive prompt（支持{prompt}占位符 — 会被替换为用户自己的提示词，若省略则附加在其后）和Negative prompt（可选）",
        helpPrompt12: "重命名后仍保留其在原定义文件中的位置；新建的Style会保存到style文件夹内专用的custom.json中，因此内置的风格包文件不会被直接修改；名称在所有Style中必须唯一",
        helpPrompt13: "保存、重命名或删除Style会立即刷新GenerateUI的Style下拉菜单、Batch标签的风格勾选列表以及Style Catalog的名称列表 — 无需重新加载",
        helpPrompt14: "列表中每个条目的名称旁都会以小徽章显示其来源文件（例如sdxl_styles_diva.json）；编辑现有Style时，该文件名也会显示在Positive prompt字段上方，并且Save按钮旁会出现「+ Add to this file」按钮 — 点击后表单会清空，可创建一个新Style并追加到同一文件，而不是默认的custom.json",
        helpPrompt15: "两个顶层标签：Form是下文所述的传统单项逐一编辑界面（AI助手/Presets/Wildcard/Style各面板）；Table将同一份数据一次性以可编辑表格形式全部显示 — 当预设、通配符文件或Style数量较多时更实用",
        helpPrompt16: "Table标签内还有四个子标签：Presets、Presets Group、Wildcards、Style — 均为与Form标签完全相同数据的可编辑表格，任一侧的修改都会同步到另一侧",
        helpPrompt17: "每个表格左侧共用一个自动编号的#列：点击编号可选中该行（红色高亮），可同时选中多行；工具栏的Delete按钮会在一次确认后删除所有选中行，Deselect用于清除选择。此设计取代了容易误触的逐行删除按钮",
        helpPrompt18: "双击行号会打开更大的提示词编辑弹窗，取代表格内较小的文本框。Presets和Style在共用的一个文本框上方显示Positive/Negative切换按钮（切换时会保留另一侧已输入的内容）；Wildcards仅显示文件内容。Save会写回并关闭弹窗，Close则放弃更改",
        helpPrompt19: "工具栏的「+ New ...」按钮会在顶部添加一个空白可编辑行，编号位置显示小图标✓（Add）／✕（Cancel）；填写内容后点击✓即可创建，点击✕则放弃该行且不保存",
        helpPrompt20: "Presets表格 — ★（收藏）和B（Batch分组）两列如同开关：点击变为金色/黄色，再次点击取消；工具栏的BC按钮可一次性清空Batch分组中的所有预设，与Form标签的Preset Manager效果相同",
        helpPrompt21: "Presets表格工具栏 — PP Copy／NP Copy用于将当前选中的单行的正/负向提示词复制到剪贴板；分组下拉框＋Add to Group可一键将所有已选中的预设添加到所选分组。在此处进行分组分配（先在Presets表格中搜索/选择，再从简短的分组列表中挑选）取代了旧版按分组选择预设的方式，后者在预设较多时已难以使用",
        helpPrompt22: "Presets Group表格 — 创建、重命名、删除分组；每个分组的成员以可删除的徽章（✕）形式显示。保留分组Batch不会显示在这里 — 它完全通过Presets表格的B列和BC按钮进行管理",
        helpPrompt23: "Wildcards表格 — 与Form标签的通配符文件管理器使用相同的文件列表；编辑File列的路径或Ext下拉框会重命名文件（先以新名称保存内容，再删除旧文件）",
        helpPrompt24: "Style表格 — 与Form标签的Style管理器使用相同的Style列表，可像Presets一样进行内联编辑",
        helpPrompt25: "Presets表格工具栏 — 搜索框旁边的★和B排序按钮，可将收藏／已加入Batch的预设排到列表顶部；两者可同时启用（★优先，B为次要条件），其余项保持原有的相对顺序",
        helpPrompt26: "Style表格工具栏——只选中一行且其File徽标不是custom.json时，「+ Add to this file」按钮才会启用：会添加一个以该文件为目标的空白行（保存前File列就会显示该文件的徽标）——与Form标签中Style管理器的同一功能（见上文）。custom.json条目或多选时按钮保持禁用，此时请改用常规的「+ New Style」按钮",
