        helpImageEditTitle: "图像编辑选项卡",
        helpImageEdit1: "基于图层的图像编辑器 — 通过多个图层（图像、文字、绘制、遮罩类型）合成图像并导出",
        helpImageEdit2: "加载图像：拖放到画布、点击Upload按钮、或通过Gallery标签工具栏的Image Edit按钮发送；第一张图像成为图层1（自动锁定）；后续图像缩放至画布大小作为新图层添加",
        helpImageEdit3: "New按钮：创建空白画布 — 输入宽高（如512x768）；清除所有现有图层并自动添加空白Layer 1",
        helpImageEditToolsTitle: "工具",
        helpImageEdit4: "Select (V)：点击选择图层；拖动移动；拖动角点手柄调整大小；拖动顶边圆形手柄旋转；双击文字图层可重新编辑；工具选项栏显示翻转H / 翻转V / 旋转角度",
        helpImageEdit5: "Draw (B)：在当前绘制图层上自由绘画；工具选项：颜色、笔刷大小、混合模式；属性面板包含用于ABR图像笔刷的MASK EDITOR ONE (COLOR)区域 — 始终显示，笔刷可用时标题为绿色，未导入笔刷时为灰色；没有任何笔刷时Select按钮为禁用状态",
        helpImageEdit6: "Text (T)：点击画布放置文字输入框；在工具选项栏设置字体、大小、粗体/斜体、对齐方式、颜色；点击OK后以精确文字边界框大小创建文字图层；用Select工具双击现有文字图层可重新编辑",
        helpImageEdit7: "Shape (S)：在画布上绘制几何图形；每个确认的图形成为独立的绘制图层；工具选项：图形类型（Rect / Ellipse / Line / FreeLine）、圆角复选框（仅Rect/Ellipse）、填充颜色+None切换（Line/FreeLine隐藏）、描边颜色+宽度+None切换（Line/FreeLine的None隐藏，始终有描边）、不透明度滑块、↩撤销按钮；拖动预览（蓝色虚线），释放确认",
        helpImageEditLayerTitle: "图层面板",
        helpImageEdit8: "图层从前景（顶）到背景（底）列出；点击图层行将其激活",
        helpImageEdit9: "👁 / 🚫 按钮：切换图层可见性",
        helpImageEdit10: "🔒 / 🔓 按钮：切换图层锁定 — 锁定图层无法移动、缩放或旋转（显示橙色边框）；加载第一张图像时图层1自动锁定以防止误操作",
        helpImageEdit11: "底部的不透明度滑块调整当前图层的透明度",
        helpImageEdit12: "类型图标：🖼 = 图像图层，T = 文字图层，✏ = 绘制图层，⬚ = 遮罩图层",
