        helpTrouble5: "LoRA Stack出现「No such file or directory」错误：该LoRA可能未被comfyui-lora-manager识别（已知问题）。请尝试其他LoRA，或检查该文件是否显示在Lora Manager自身的界面中",
        helpTrouble6: "移动或删除模型后出现模型加载错误：ComfyUI会缓存文件路径，可能仍引用旧位置。请通过ComfyUI菜单执行Hard Reset（Queue → Hard Reset）或重启ComfyUI以清除缓存。",
        helpTrouble7: "Tagger标签不显示模型：确认ComfyUI/models/tagger/<模型名>/文件夹存在且包含.onnx或.h5文件；如未安装onnxruntime，请运行：python_embeded\\python.exe -m pip install onnxruntime",
        helpTrouble8: "Model 标签页显示的 Checkpoint 与预期不符（例如无论加载哪个工作流都显示相同模型）：工作流文件中保存的 Checkpoint 实际未安装，加载时已被静默替换为其他已安装模型，此时会弹出包含原始（未找到）模型名称的错误提示。请在 Model 标签页手动选择正确的 Checkpoint，或在设置标签页启用\"默认 Checkpoint\"，在每次加载时强制应用一个已验证可用的模型。",
        helpTrouble9: "点击 Generate 后，执行的是与刚加载的工作流不同的工作流：Batch 子标签页中的某个批量类型（Checkpoint/LoRA/Prompt/Workflow/Sampler/Scheduler）复选框仍处于开启状态。只要有任意批量类型处于启用状态，Generate 按钮执行的就是批量选择的内容，而不是当前加载的工作流。请打开 Batch 子标签页，关闭已启用的批量类型复选框。",
